    @classmethod
    def parse(cls, raw: Any) -> "StixObject":
        if not isinstance(raw, dict):
            raise ValidationError("STIX object body must be a JSON object")
        type_name = raw.get("type")
        if type_name not in OBJECT_TYPES:
            raise ValidationError(
