def _start_snapshot(
    self,
    collection_id: str,
    requested: tuple[str, ...] | None,
    page_size: int,
    documents: list[dict[str, Any]],
) -> Result:
    """Freeze the current result set so later writes stay out of this round."""
    type_echo = self.store.encode(list(requested)) if requested is not None else None
